def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    from collections import deque

    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, cells))

    # The distinctive long component acts as a color key; recolor the closest
    # separate object to that key.
    key = max(comps, key=lambda z: len(z[1]))
    kc, kcells = key
    best = None
    for color, cells in comps:
        if cells is kcells or color == kc:
            continue
        d = min(abs(y-a)+abs(x-b) for y,x in cells for a,b in kcells)
        if best is None or d < best[0]:
            best = (d, cells)
    out = [row[:] for row in grid]
    if best:
        for r, c in best[1]:
            out[r][c] = kc
    return out
